import{_ as t,o as s,c as o,a2 as a}from"./chunks/framework.C3idr2hZ.js";const n="/orc/screens/dashboard-light.png",r="/orc/screens/session-home-desktop.png",i="/orc/screens/session-home-phone.png",d="/orc/screens/session-list-phone.png",l="/orc/screens/dashboard.png",c="/orc/screens/tasks.png",h="/orc/screens/task-detail.png",p="/orc/screens/task-flow.png",g="/orc/screens/sessions.png",u="/orc/screens/desktop-chat-browser-control.png",m="/orc/screens/desktop-browser-settings.png",f="/orc/screens/desktop-preview-browser.png",b="/orc/screens/desktop-preview-markdown.png",w="/orc/screens/terminals.png",k="/orc/screens/knowledge.png",y="/orc/screens/jobs.png",v="/orc/screens/jobs-editor.png",C="/orc/screens/settings.png",S="/orc/screens/settings-agents.png",T="/orc/screens/chat-agent-picker.png",x="/orc/screens/chat-composer-390.png",E=JSON.parse('{"title":"Desktop app and web dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"docs/desktop-and-web.md","filePath":"docs/desktop-and-web.md","lastUpdated":1794514078000}'),P={name:"docs/desktop-and-web.md"};function q(A,e,R,_,I,O){return s(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="desktop-app-and-web-dashboard" tabindex="-1">Desktop app and web dashboard <a class="header-anchor" href="#desktop-app-and-web-dashboard" aria-label="Permalink to &quot;Desktop app and web dashboard&quot;">​</a></h1><p>A tour of every page in the ORC dashboard and what the desktop app adds on top of it.</p><p>The dashboard is served by the daemon at <code>http://localhost:7700</code>. The desktop app shows the same dashboard in its own window, so everything below applies to both.</p><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Contents</th></tr></thead><tbody><tr><td>Sidebar</td><td>Activity, Chat, Tasks, Knowledge, Terminals, Library, Settings. Shows the execution host, for example <code>Connected (local)</code>.</td></tr><tr><td>Project picker</td><td>Scopes most pages to one project, all projects, or unassigned items. A project with sessions waiting on you shows how many.</td></tr><tr><td>Chat panel</td><td>Talk to any enabled coding agent from any page. Pick the agent and model at the top. Claude and Codex run natively; OpenCode uses direct ACP; other agents run through ACPX.</td></tr><tr><td>Command palette</td><td><strong>Ctrl+K</strong> (<strong>Cmd+K</strong> on macOS) to search and run commands</td></tr><tr><td>Next session</td><td><strong>Alt+J</strong> (<strong>Option+J</strong> on macOS) opens the next session that needs you, then the next finished session you have not seen. It does nothing while you are typing.</td></tr></tbody></table><p>Popup menus and pickers across the dashboard close when you tap outside or press Escape, including project, session, document and terminal actions. Tapping the terminal canvas also dismisses an open menu. Interacting inside a picker or its folder dialog keeps it usable without discarding your draft.</p><p>Pages are grouped in the sidebar:</p><table tabindex="0"><thead><tr><th>Group</th><th>Pages</th></tr></thead><tbody><tr><td>Activity</td><td>Activity, Sessions, Jobs, Webhooks, Audit</td></tr><tr><td>Chat</td><td>Chat</td></tr><tr><td>Tasks</td><td>Tasks</td></tr><tr><td>Knowledge</td><td>Knowledge base, Memories</td></tr><tr><td>Terminals</td><td>Terminals</td></tr><tr><td>Library</td><td>Skills, Packages, Agents, Rules, Scratchpads</td></tr><tr><td>Settings</td><td>Settings</td></tr></tbody></table><p>Projects has its own page at <code>/projects</code>. Every page has a shareable URL.</p><p>The sun and moon button in the header switches between the dark and light themes:</p><p><img src="'+n+'" alt="Dashboard in the light theme"></p><h2 id="chat-page" tabindex="-1">Chat page <a class="header-anchor" href="#chat-page" aria-label="Permalink to &quot;Chat page&quot;">​</a></h2><p><strong>Chat</strong> in the sidebar, under Activity, opens the chat page at <code>/chat</code>. It is a regular page: the workspace header keeps your navigation and notifications, the sidebar keeps whatever width you chose, and <strong>Chat</strong> shows as the active page. The chat panel&#39;s full-screen button, and the full-screen button on <strong>Sessions</strong> (on the page or on a row) or in the <strong>Terminals</strong> session list, open the same page.</p><p>Below 1280px wide, the chat has no side panel: starting a chat from any page opens the chat page instead.</p><ul><li><strong>Session list</strong>: chats, coding agents running in ORC terminals, and live sessions discovered from your coding agents, each with its state. Click a chat to read it, a terminal agent to see its terminal, or a discovered session to resume it in chat. Collapse the list to a rail of icons with its state marks; expand it again from the rail.</li><li><strong>Inspector</strong>: the panel button in the header shows the host, folder, branch, changed files, linked task and pull request for the selected session. When a terminal is running in that folder, a <strong>Diff</strong> tab shows its Git changes.</li><li><strong>Terminal drawer</strong>: the terminal button in the header opens a shell in the session&#39;s folder below the conversation.</li><li>Drag a splitter, or focus it and use the arrow keys, to resize the list, inspector or drawer. Double-click to reset. The width is remembered.</li><li>The page keeps the workspace header and its single notification bell, and the sidebar at the width you chose. <strong>Close chat</strong> returns to the page you came from.</li><li>The URL keeps the selected session and which panels are open, so reload and Back restore them.</li><li>The header shows the recorded project and session title. Unlinked terminal agents show <strong>Unknown</strong> until agent activity supplies a state; they appear only in All projects while project ownership is unavailable. The Activity session list uses the same compact row design, retaining search, filters, task links and resume actions.</li></ul><p>On a phone the list opens full screen from <strong>Sessions</strong> in the chat header and the inspector opens as a sheet. The three-dot <strong>Session actions</strong> menu shows labeled actions with touch-sized rows on phones. It closes when you tap elsewhere in the chat or press Escape. Choosing an action also closes the menu; opening Session settings keeps the conversation and your draft in place. Agent, workspace and branch pickers also close when you tap outside them. Opening the list sets <code>sessionList=show</code> in the URL, so reload and Back restore it. Closing the page also returns to the original page after navigating Back and Forward.</p><p><img src="'+r+'" alt="Session home with its inspector and demo data"></p><img src="'+i+'" alt="Phone conversation with compact composer controls" width="260"><img src="'+d+'" alt="Full-screen session list on a phone" width="260"><h2 id="activity" tabindex="-1">Activity <a class="header-anchor" href="#activity" aria-label="Permalink to &quot;Activity&quot;">​</a></h2><p><img src="'+l+'" alt="Activity"></p><p>The <strong>Activity</strong> page: task metrics plus recent jobs, memories and sessions for the selected project.</p><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><p><img src="'+c+'" alt="Tasks"></p><p>The task board. Switch between <strong>Board</strong> (kanban) and <strong>Table</strong> views and filter the list. The GitHub panel lists issues and pull requests from known repositories (yours, assigned to you, or all open) and links them to tasks.</p><p>Open a task to see its body, status, comments, linked sessions and Git links, and its flow run:</p><p><img src="'+h+'" alt="Task detail"></p><p><strong>Edit task → View flow</strong> shows the nodes and edges of the task&#39;s <a href="./task-flows">flow</a>, including loops back for review:</p><p><img src="'+p+'" alt="Task flow"></p><h2 id="sessions" tabindex="-1">Sessions <a class="header-anchor" href="#sessions" aria-label="Permalink to &quot;Sessions&quot;">​</a></h2><p><img src="'+g+'" alt="Sessions"></p><p>Live and archived sessions from Claude Code, Codex, Cursor, Gemini CLI and OpenCode on this machine or the selected host. Working sessions update live; waiting sessions stay available to resume in a terminal or in chat. Search across archived conversations. See <a href="./live-sessions">Live sessions</a>.</p><p>Filter the list by state with <strong>All</strong>, <strong>Needs you</strong>, <strong>Working</strong> and <strong>Done</strong>. Each filter shows its count, and failed sessions count as Needs you. A session that finished after you last opened it shows <strong>Done</strong> until you open it. This browser remembers what you have seen. The chat session history has the same filters.</p><p>While your pointer is over the list, or a row has keyboard focus, rows stay where they are. States still update in place. When the order would change, an <strong>N updated</strong> button appears. Click it, or move away from the list, to apply the new order.</p><h2 id="terminals" tabindex="-1">Terminals <a class="header-anchor" href="#terminals" aria-label="Permalink to &quot;Terminals&quot;">​</a></h2><h3 id="desktop-browser-files-and-editor" tabindex="-1">Desktop browser, files and editor <a class="header-anchor" href="#desktop-browser-files-and-editor" aria-label="Permalink to &quot;Desktop browser, files and editor&quot;">​</a></h3><p>In the Electron desktop app, <strong>File → Browser and files</strong> (Ctrl/Cmd+Shift+B), or <strong>Browser and files</strong> in the tray menu, opens a panel beside your conversation. Chat links and file attachments open in this panel. Enter an HTTP/HTTPS address and use Back, Forward and Reload. The external-link icon opens the page in your system browser; Ctrl/Cmd-clicking a web link does the same.</p><p>Each conversation keeps its own browser and file tabs. The panel stays docked beside the conversation and opens only when you ask for it or follow a link; drag the divider (or use arrow keys on it) to resize. The <strong>Files</strong> tab browses every file in the session&#39;s folder and opens a file in an editor tab. Closing the panel keeps tabs and drafts in memory; closing a modified file asks before discarding it. Reloading or quitting discards these previews after the unsaved-change warning.</p><p>The folder icon (<strong>Open file</strong>) uses the native picker for local files. Chat and MCP file paths resolve inside the selected session&#39;s folder on its execution host; paths outside that folder and symlinks escaping it are denied. Remote file previews require Python 3 on the SSH host. Files must be UTF-8 text up to 1 MiB. Markdown has Read, Edit and Split modes; code uses the existing editor. Text up to 200 KB can be saved explicitly. A save fails if the file changed on disk, keeping your draft until you reload or resolve the change. HTML stays source code. The external-link icon opens the source in VS Code, including known SSH hosts; it is disabled when the desktop cannot identify a remote API host&#39;s filesystem.</p><p>PNG, JPEG, GIF, WebP, BMP and ICO images can also be previewed, up to 8 MiB and 16 megapixels for native-picker images. Images are read-only; native-picker images use native decoding and display a static image. Workspace images use the browser&#39;s image decoder. PDF and Office previews are not included.</p><p>The browser uses a separate session without ORC&#39;s API credentials, cookies or desktop bridge. Camera, microphone, location and other site permissions are blocked. Browser downloads are staged privately (16 MB each, four across the app); <strong>Browser profile, display &amp; recording</strong> lists their status and saves completed files to the selected chat workspace. Interrupted/failed downloads are never reported as saved. Each chat starts with a temporary cookie/storage profile. <strong>Settings → Browser → Saved browser profiles</strong> creates named profiles; select one under <strong>Browser profile, display &amp; recording</strong> in the browser panel to remember site logins. Selecting the same profile in another chat explicitly shares that profile&#39;s site storage. Temporary chats stay isolated. Profile choices and saved cookies survive app restart; session-only cookies follow the site&#39;s expiry rules. Switching profiles closes that chat&#39;s browser tabs after confirmation and preserves file drafts. Use <strong>+</strong> to open a browser tab and each tab&#39;s close button to close it. Popups open another isolated tab. Limits are eight tabs per chat and 24 total; reaching a limit asks you to close a tab, without eviction. Tab IDs, URLs and the selected tab restore when you return after app restart. Temporary mode does not persist cookies; saved tab URLs are still restored. Browser settings also offers profile rename and removal. Removal asks for native confirmation, closes its tabs, clears cookies/site data/cache and resets chat selections.</p><p><strong>Import selected browser logins</strong>, under Browser settings, connects to a local Chrome/Edge debugging endpoint you explicitly enable. Choose the destination ORC profile, enter the loopback debugging port, approve any source-browser prompt, then select sites from its open pages. Only those sites&#39; applicable cookies are copied; their values and the source connection never reach agents or the API. The connection closes after import or cancellation. Live transfer copies cookies applicable to the selected site&#39;s root and currently open page path; passwords, localStorage, IndexedDB and device-bound sessions are not transferred. Partitioned cookies are skipped and counts are reported. Verify the login; some sites require signing in again. Modern Windows Chrome/Edge app-bound cookie files cannot be decrypted by ORC. Chrome&#39;s newer native consent flow and Mac/Linux interaction have not been validated here; the verified source was an isolated Windows Edge profile with a loopback debugging port. Existing personal profiles may not expose one.</p><p><strong>Scan browser profiles</strong> provides direct cookie-store import from Firefox/Zen, Safari on macOS, and supported Chromium-family stores on macOS/Linux. Legacy Windows Helium DPAPI stores are supported; app-bound Windows stores require the live connection. Select a source profile and individual sites. Reads use readonly SQLite snapshots; keys are obtained only after selection through OS facilities. macOS may request Keychain/Full Disk Access approval; Linux encrypted stores need <code>secret-tool</code> and an unlocked Secret Service. Missing keys and skipped cookies are reported, never treated as a guaranteed login. Containers and partitioned cookies are excluded. Direct Firefox import was exercised with isolated Windows demo data; other OS integrations still require their native platform acceptance checks.</p><p>Expand <strong>Browser display &amp; recording</strong> to change appearance/viewport, record the guest page, save WebM to the chat workspace, and play/download it. UI recording lasts up to 60 seconds; agent requests can choose up to 180 seconds. Recordings are limited to 16 MB and contain only the browser guest, without audio or ORC UI. If workspace saving fails, the completed file remains downloadable in that window.</p><p>Agents can use <a href="./mcp#desktop-preview-tools">preview MCP tools</a> to show a file or URL in the selected conversation. <strong>Allow agent browser control</strong>, on by default, is controlled in the chat&#39;s <strong>Session settings</strong> before you open a preview. It permits snapshots, screenshots, clicking, typing, key presses, scrolling, hovering, selecting, dragging, condition waits, guest JavaScript evaluation, cross-origin frame targeting, semantic locators, dialogs, recording, appearance, viewport changes and explicit workspace-file uploads/download retrieval. This includes pages you sign into there. Turning the switch off revokes control. These tools cannot inspect the ORC app or its bridge or edit preview files. Upload paths must remain inside the chat&#39;s trusted workspace. The guest has a minimal standard <code>prompt()</code> adapter because Electron disables that browser function; it exposes no application API, credentials, filesystem access or general IPC. Browser content is untrusted page data, never agent instructions. If a mutating browser command is still pending when control is revoked or its guest is hidden/switched, ORC closes that guest to prevent delayed execution. The tab shows an interruption message; <strong>Reload</strong> restores its URL and profile. File drafts are preserved. An evaluation timeout can require the same recovery.</p><p><img src="'+u+'" alt="Browser access in a demo chat&#39;s Session settings"></p><p><strong>Settings → Browser</strong> controls agent browser access for the whole desktop and whether chat web links open in ORC or your system browser. Settings are stored in <code>browser-preferences.json</code> in Electron&#39;s user-data folder and survive restarts. Per-chat permissions use <code>browser-chat-permissions.json</code>; named profile metadata and explicit chat selections use <code>browser-profiles.json</code>. These metadata files do not contain cookies or passwords; Chromium owns the separate profile partitions. Turning global agent access off overrides every chat&#39;s switch immediately. With global access on, the chat&#39;s <strong>Session settings</strong> switch can still disable control for that conversation. The browser toolbar does not contain a second access switch. Files and explicit MCP preview requests continue to open in the panel.</p><p><img src="'+m+'" alt="Desktop Browser settings with demo data"></p><p>This flow is desktop-only; the web and phone UI are unchanged.</p><p><img src="'+f+'" alt="Browser beside a demo conversation"></p><p><img src="'+b+'" alt="Markdown editing beside a demo conversation"></p><p><img src="'+w+'" alt="Terminals"></p><p>Browser terminals for shells and coding agents, with split panes and Files and Git panels beside them. Terminals run on the selected execution host. See <a href="./terminal-workspace">Terminal workspace</a>.</p><h2 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h2><p>Create, edit and archive projects. A project has a name, description, tags and an optional Git remote URL. Deleting a project deletes its memories and scratchpads and keeps its tasks, jobs and sessions without a project.</p><h2 id="memories" tabindex="-1">Memories <a class="header-anchor" href="#memories" aria-label="Permalink to &quot;Memories&quot;">​</a></h2><p>Short project facts (ports, conventions, decisions) that agents load at session start. Create, edit, and view each memory&#39;s change history. Under <strong>Knowledge → Memories</strong>.</p><h2 id="knowledge" tabindex="-1">Knowledge <a class="header-anchor" href="#knowledge" aria-label="Permalink to &quot;Knowledge&quot;">​</a></h2><p><img src="'+k+'" alt="Knowledge"></p><p>Knowledge bases: upload PDFs, Office files, HTML, CSV and Markdown, write Markdown in place, or register a folder to copy in. Search returns cited passages. Each knowledge base can have a digest agent that maintains it on a schedule.</p><h2 id="jobs" tabindex="-1">Jobs <a class="header-anchor" href="#jobs" aria-label="Permalink to &quot;Jobs&quot;">​</a></h2><p><img src="'+y+'" alt="Jobs"></p><p>Scheduled and on-demand automation. A job runs a shell command, an agent or creates a task, triggered manually, by cron, by a file watch, once, or by a webhook. Each job keeps its run history with logs and linked agent sessions.</p><p>The job editor uses <strong>Trigger</strong>, <strong>Destination</strong> and <strong>Settings</strong> tabs. Choose Manual, Webhook or Schedule; schedules offer time/day controls and <strong>Advanced cron</strong>, with an explicit timezone. Existing watch, one-shot and bridge-message jobs keep their trigger. New jobs stay disabled until you enable them; a disabled job can still run manually.</p><p>Destination selects the project, working directory and execution host (local or a configured SSH host). Commands offer sh, bash, zsh, fish, PowerShell and cmd presets, plus a custom executable and one argument per line. The script is appended as the final argument, so a custom interpreter needs its command option, such as <code>-c</code>. The interpreter must be installed on the destination. Host default uses sh on Unix and Windows PowerShell on Windows; jobs saved before this setting retain sh.</p><p>Agent jobs save a prompt, backend, optional model, explicit automatic tool approval and supported launch options. Agent and model use the same picker as Chat: enabled agents, models reported by the provider on the job&#39;s selected host/directory, Agent default and an explicit Custom model option. A saved model remains selectable if discovery is temporarily unavailable. Changing agents clears the previous model and launch options. New agent jobs default to an isolated, detached Git worktree for each run. <code>HEAD</code> inherits the project checkout&#39;s current commit; override it with a branch or remote-tracking ref. ORC does not fetch, reset or push the base. <strong>Clean up worktree after a successful run</strong> is off by default. When enabled, cleanup removes only a successful, clean worktree with no commits absent from its starting base; failed runs, untracked/ignored files and new commits are retained. Run history records the path and cleanup result. HTTP-only agent backends cannot use these local host, worktree or environment settings.</p><p>Environment variables live under Settings. Mark a value <strong>Secret</strong> to mask its input, encrypt it at rest and omit its value from read responses. After saving, leave a saved secret blank to keep it; enter a replacement to rotate it. Exact secret values are redacted from job output and saved agent summaries, including across output chunks. This does not scrub transformed values or files and logs written by the script itself. Values are single-line; <code>ORC_</code> names are reserved. Back up <code>~/.orc/secret.key</code> with the database: saved secrets cannot be decrypted without that machine key.</p><p>To see a result, open the job and select <strong>View result</strong> under <strong>Recent runs</strong>. This shows the saved output and errors. <strong>Session summary</strong> opens the audit record. For an agent run with a native session ID, <strong>Open agent session</strong> opens the actual conversation in Sessions, where the existing transcript/resume controls apply. ORC discovers that conversation on the run&#39;s own host without changing the globally selected host. If the provider has not retained a conversation yet, the saved result remains available and the interface explains that the native conversation is missing.</p><p><img src="'+v+'" alt="Job schedule editor"></p><h2 id="webhooks" tabindex="-1">Webhooks <a class="header-anchor" href="#webhooks" aria-label="Permalink to &quot;Webhooks&quot;">​</a></h2><p>Inbound event sources. Configure a webhook once, then connect it to one or more jobs, each with its own event filters and action.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>When a session you are not viewing needs your approval, has a question or fails, ORC shows a <strong>Needs you</strong> notification and plays a short chime. Notifications settle for about one second before appearing and repeated snapshots do not repeat the alert. The header bell opens a menu containing generic notifications, including human requests, agent outcomes and job results. Open a request to answer or review its action. Read and dismissed state is shared across clients.</p><p>Desktop browsers show toasts. Needs-you toasts stay until dismissed or resolved; <strong>Done</strong> toasts are silent and close after six seconds, pausing on hover or focus. Sessions finishing together collapse into one notification. Use <strong>Alt+N</strong> or <strong>Open notifications</strong> in the command palette to reach notifications.</p><p>On all screens, the bell in the workspace header shows an unread count, including while the chat is open. New notifications never open the panel automatically. Tap the bell to read or dismiss them. History remains until dismissed or expired (30 days by default). Configure notification and audit retention in Settings → Storage. See <a href="./notifications">Notifications</a> and <a href="./human-requests">Human requests</a>.</p><p><strong>Settings → Notifications → Sound</strong> controls the browser chime, volume and per-project sound mute. Preferences are saved in this browser. Audio starts after your first interaction. Browser/PWA push remains separately opt-in and requires HTTPS (and Home Screen installation on iOS); it delivers background approvals, questions, chat replies and job results while ORC is unfocused. Job pushes follow the job&#39;s notify setting and start with new runs. See <a href="./install">Installation</a>.</p><p>The Electron desktop app also sends native notifications while its window is unfocused, minimized or hidden. Clicking one brings ORC forward, opens its destination and marks that notification read, clearing it from the inbox. A grouped done toast opens its destination only; clear the collapsed items from the notification menu. Done notifications are silent; native Needs-you sound follows the OS.</p><h2 id="browser-app-and-updates" tabindex="-1">Browser app and updates <a class="header-anchor" href="#browser-app-and-updates" aria-label="Permalink to &quot;Browser app and updates&quot;">​</a></h2><p>The dashboard installs as a browser app and serves an offline shell when the network is unreachable. An open tab or installed app runs the build it was loaded with, and the server replaces that build when it is updated. Reaching a page whose code is gone then reloads the app once, without asking, so unsaved input in the current page is lost; the reload loads the current build. If it does not fix the problem, ORC shows the failing error with <strong>Reload</strong> and <strong>Copy details</strong> instead of a generic error page, so a report carries the real message and stack.</p><h2 id="audit" tabindex="-1">Audit <a class="header-anchor" href="#audit" aria-label="Permalink to &quot;Audit&quot;">​</a></h2><p>Lifecycle and knowledge events with filters and expandable details. Recorded session summaries remain in collapsed history. Audit retention defaults to 90 days and is configurable in Settings → Storage. Use Sessions to read full conversations or resume an agent.</p><h2 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills&quot;">​</a></h2><p>Reusable agent instructions stored as skill folders. Import skills from a repository or from local agent folders, create your own, edit files, view history, and assign skills to projects. See <a href="./skills">Skills</a>.</p><h2 id="packages" tabindex="-1">Packages <a class="header-anchor" href="#packages" aria-label="Permalink to &quot;Packages&quot;">​</a></h2><p>Packages bundle instructions, skills and tools for reuse. Launch a package in chat or a terminal on the host and folder you choose. See <a href="./agent-packages">Agent packages</a>.</p><h2 id="agents" tabindex="-1">Agents <a class="header-anchor" href="#agents" aria-label="Permalink to &quot;Agents&quot;">​</a></h2><p>Shared specialist agent definitions: instructions, model and tools, reusable across coding agents and packable into packages. Under <strong>Library → Agents</strong>.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><p>Applied rules and their outcomes per workspace, plus rule settings for enforcement and agent assignment. See <a href="./agent-rules">Agent rules</a>.</p><h2 id="scratchpads" tabindex="-1">Scratchpads <a class="header-anchor" href="#scratchpads" aria-label="Permalink to &quot;Scratchpads&quot;">​</a></h2><p>Working documents, diagrams and HTML pages that you or an agent create and come back to. Agents use the <code>pad_*</code> MCP tools. Share one by copying its link.</p><p>HTML pads receive the <strong>ORC HTML kit</strong> in both the editor preview and chat artifacts: dashboard theme tokens, base styles, cards, tables, stats, badges, tabs and chart wrappers. Use <code>orc-*</code> classes to build a native-looking page without a custom <code>&lt;style&gt;</code> block. The kit is inlined at render time, needs no network request, and does not change the saved HTML. Custom CSS and JavaScript still work.</p><p>Pin the kit stylesheet in your HTML head to keep its version as the kit evolves:</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">meta</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;orc-kit&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> content</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>Bundled older versions remain available. A missing or unknown version uses the current kit. Both previews follow the dashboard&#39;s light/dark theme; changing the theme rebuilds the iframe document, resetting its running scripts and local UI state. The saved pad content stays the same.</p><p>Kit tabs support clicking, Left/Right arrows with wrapping, and Home/End. Only the selected panel is shown. The kit does not grant ORC API access: editor pads still require <strong>Render with ORC access</strong>, and chat artifacts retain their opaque sandbox and network-blocking policy. Prefer inline SVG for charts that must work in both views; a CDN chart library is blocked in chat.</p><p>For concise component markup, use built-in custom elements such as <code>&lt;orc-card&gt;</code>, <code>&lt;orc-stat label=&quot;Open tasks&quot; value=&quot;12&quot;&gt;</code>, <code>&lt;orc-badge tone=&quot;success&quot;&gt;</code>, <code>&lt;orc-table&gt;</code> and <code>&lt;orc-chart&gt;</code>. <code>&lt;orc-tabs&gt;</code> generates accessible tab controls from labeled <code>&lt;orc-tab&gt;</code> panels. These components reuse the kit with no additional dependencies or network requests; ordinary HTML with <code>orc-*</code> classes remains supported.</p><p>Agents can load the component list, copy-paste skeleton and chart guidance with <code>skill_read</code> for <code>orc-platform</code>, ref <code>references/html-kit.md</code>. See <a href="./skills">Skills</a>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p><img src="'+C+'" alt="Settings"></p><table tabindex="0"><thead><tr><th>Section</th><th>Controls</th></tr></thead><tbody><tr><td>Connection</td><td>API URL for this browser</td></tr><tr><td>Security</td><td>Sign-in status and sign-out, default sign-in lifetime, allowed web origins, access tokens (minted by entering the secret)</td></tr><tr><td>Appearance</td><td>Theme</td></tr><tr><td>Execution host</td><td>Run agents, terminals and git locally or on an SSH host from <code>~/.ssh/config</code></td></tr><tr><td>Server</td><td><strong>Restart ORC server</strong> (closes terminals, keeps settings, reconnects)</td></tr><tr><td>Notifications</td><td>In-app updates, browser chime/volume/project mute, and opt-in browser/PWA push for background approvals, questions, chat replies and job results. Push needs HTTPS.</td></tr><tr><td>Agents</td><td>Which coding agents appear in the chat agent picker, channel agent choices and the terminal launcher. Claude Code, Codex and Pi are native; OpenCode runs over direct ACP; Cursor, Gemini CLI, GitHub Copilot, Qwen Code, Factory Droid, Kimi CLI, Kiro CLI and any custom agent id run through ACPX. First startup selects installed agents from Codex, Claude, Cursor, Gemini CLI and OpenCode and saves that selection. Copilot can be enabled in Settings. Later selections are preserved even if an installation is missing. The terminal launcher only lists enabled agents installed on the selected host.</td></tr><tr><td>Channels</td><td>Telegram and Slack connections</td></tr><tr><td>Chat</td><td>Default models, instructions, tools and permission mode for chat</td></tr><tr><td>MCP</td><td>Build the MCP config snippet for your agent. See <a href="./connect-agents">Connect agents</a>.</td></tr><tr><td>Integrations</td><td>APIs and MCP servers in the <code>spec</code> CLI registry</td></tr><tr><td>Knowledge</td><td>Parser, embeddings and knowledge defaults</td></tr><tr><td>Terminals</td><td>Terminal font for new terminals</td></tr><tr><td>Storage</td><td>Where settings are stored</td></tr><tr><td>About</td><td>Server, desktop and Electron versions, platform, runtime, data folder, uptime, project links, and desktop update channel</td></tr></tbody></table><p><img src="'+S+'" alt="Coding agents settings"></p><p>Enabled agents, including custom ACPX ids, appear in the chat agent picker:</p><p><img src="'+T+'" alt="Chat agent picker"></p><h2 id="chat-turn-progress" tabindex="-1">Chat turn progress <a class="header-anchor" href="#chat-turn-progress" aria-label="Permalink to &quot;Chat turn progress&quot;">​</a></h2><p>Finished turns fold tool calls and intermediate narration into one expandable line; your message and the final reply remain visible. Expand it to inspect file diffs, commands and output, reads, and searches. Failed tools stay marked.</p><p>During a response, a quiet status line shows elapsed time and the current tool. Scrolling up pauses automatic following; <strong>Jump to latest</strong> returns to the bottom. Stop remains beside Send. Working indicators are static.</p><p>Each turn keeps its duration and completed, stopped, or failed outcome across reloads. Duration uses the agent&#39;s reported value when available, otherwise server elapsed time, including waits for input. Older turns without timing show counts only. Stopped turns retain partial work; unfinished tool calls read <strong>Incomplete</strong>. Individual tool durations are not shown.</p><p>A turn that goes quiet does not run forever: after 15 minutes without any agent activity ORC stops it, and the conversation and a notification say it was stopped for inactivity. A turn waiting for your answer or approval, or with a command still running, is not idle and is not stopped; a 4-hour absolute limit still applies so a stuck agent cannot hold a chat worker indefinitely.</p><h2 id="composer-controls" tabindex="-1">Composer controls <a class="header-anchor" href="#composer-controls" aria-label="Permalink to &quot;Composer controls&quot;">​</a></h2><p>The composer groups folder, branch, agent/model and permissions into compact controls. Phones and narrow desktop panels use icons; wide composers show labels. Send queues the next message while a reply is running. If this session is already responding, or every chat worker is busy, that message stays queued and sends when the turn ends, without an error. Open the pending list to edit a message, move it up or down, remove it, or send it ahead of the current reply. An expanded pending list stays open across busy-worker retries. After it drains, the next list starts collapsed. If a first send loses its connection, chat looks for the original message and reconnects to its thread. Recovery stops after 15 seconds, or 60 seconds when the server may still be preparing the turn. If recovery cannot find it, the message returns to a paused queue with its attachments. Retrying keeps the message&#39;s ID so the server can recover the original turn without starting another one. Every icon has an accessible name and opens its picker with the full details; phone touch targets are at least 44px. Send stays visible at the right.</p><p>The folder picker shows the full path, copy action, recent folders, host choices when configured, and browsing. Branch/worktree controls appear for Git folders. Folder and branch controls hide after launch; conversation details show the working folder. Changing agent after launch starts a separate session. The model picker disables changes during a response or when the backend selects its own model. Effort stays in agent options. The permissions control appears for a non-default mode only when the backend supports changing it live.</p><p>Pasting at least 16 KiB or 200 lines attaches the text as <code>pasted-text-N.txt</code>. Use <strong>Ctrl/Cmd+Shift+V</strong> to paste inline instead. Typing <code>@</code> does not attach files.</p><img src="'+x+'" alt="Compact composer icons on a phone" width="260"><h2 id="desktop-app-only" tabindex="-1">Desktop app only <a class="header-anchor" href="#desktop-app-only" aria-label="Permalink to &quot;Desktop app only&quot;">​</a></h2><p>The desktop app is an Electron shell around the same dashboard. On top of the browser experience it:</p><table tabindex="0"><thead><tr><th>Capability</th><th>Detail</th></tr></thead><tbody><tr><td>Runs the daemon for you</td><td>Reuses a verified local daemon, including one on another port, or starts the bundled <code>orc</code> daemon</td></tr><tr><td>Configures auth</td><td>Generates an API secret for a daemon it starts when none is set, and sends the configured secret automatically. No sign-in screen.</td></tr><tr><td>Installs the CLI</td><td><code>~/.orc/bin/orc</code>, added to your shell <code>PATH</code></td></tr><tr><td>Tray icon</td><td><strong>Open orc</strong>, <strong>Start at login</strong> toggle, <strong>Quit orc</strong></td></tr><tr><td>Start at login</td><td>On by default, starts hidden in the tray</td></tr><tr><td>Keeps running when closed</td><td>Closing the window hides it; the tray icon and the daemon keep running. <strong>Quit orc</strong> in the tray (or <strong>Cmd+Q</strong> on macOS) quits.</td></tr><tr><td>Recovers from startup failures and crashes</td><td>Waits briefly for a starting daemon, then offers <strong>Retry</strong> or <strong>Quit</strong> if it cannot connect</td></tr><tr><td>Remembers the window</td><td>Size, position and maximized state</td></tr><tr><td>Updates</td><td>Installed macOS, Windows and Linux apps check GitHub Releases at startup and every four hours, download in the background, and offer <strong>Restart to update</strong></td></tr></tbody></table><p>Quitting the app (<strong>Quit orc</strong>) stops the daemon only if the app started it.</p><p>If another application occupies the configured port, desktop automatically starts ORC on an available port bound to <code>127.0.0.1</code>. It saves the successful endpoint in <code>~/.orc/config.json</code>, so the CLI and stdio MCP use the same port by default. Explicit CLI flags, environment variables and project configuration keep their normal precedence; update pinned ports or URLs in external integrations yourself.</p><p>Desktop checks the daemon&#39;s runtime identity, compatible version (same major and minor), database, configuration and authentication before attaching. It never starts another daemon while the daemon PID is alive, even if that daemon is unhealthy or uses different data. Authentication and configuration errors offer <strong>Retry</strong> or <strong>Quit</strong>, with the reason shown. It does not stop an existing daemon or the application occupying the preferred port.</p><p><strong>Upgrading an already-running older daemon:</strong> releases without <code>daemon.json</code> cannot provide this identity check. Stop that daemon once and start it with the updated ORC, then choose <strong>Retry</strong> in desktop. Desktop does not attach to an unverified daemon or send it the configured secret.</p><p>Command-line flags for the app executable:</p><table tabindex="0"><thead><tr><th>Flag</th><th>Effect</th></tr></thead><tbody><tr><td><code>--hidden</code></td><td>Start without opening a window</td></tr><tr><td><code>--quit</code></td><td>Quit the running instance and the daemon it started</td></tr></tbody></table><p>Links to other sites open in the desktop preview panel. Use its external-link icon or Ctrl/Cmd-click a web link to open your system browser.</p><p>Install a desktop build containing this updater manually once. Older builds do not have an updater and cannot automatically install the feature itself; subsequent macOS, Windows and Linux updates can use the flow below.</p><p>An installed macOS, Windows or Linux app checks <a href="https://github.com/niradler/orc/releases" target="_blank" rel="noreferrer">GitHub Releases</a> for updates when it starts and every four hours. The download runs in the background. <strong>Settings → About</strong> shows the current version, the update channel, <strong>Check now</strong>, and the last result. <strong>Restart to update</strong> installs the download; quitting alone does not apply it. The app stops the daemon it started, then the new version starts that daemon again. Tasks and sessions stay in <code>~/.orc</code>. A daemon the app did not start is left running.</p><p><strong>Stable</strong> uses the latest GitHub release. <strong>Preview</strong> also accepts a newer prerelease. Uncheck <strong>Check for updates</strong> to stop automatic checks; <strong>Check now</strong> still works. These choices are stored in the desktop app&#39;s own settings, not in <code>~/.orc/config.json</code>. Source runs and <code>electron .</code> do not download updates.</p><p>Wait for an active check or download to finish before changing channels. Changing channels discards the previous channel&#39;s ready update. Failed settings saves retain the prior preferences and show an error; failed update actions can be retried.</p><p>Windows installs the NSIS package. Linux replaces the AppImage. macOS verifies the release disk image and its app bundle, then replaces the app through a separate installer helper and keeps the previous app for recovery. The Mac installation folder must be writable; updates work without a paid Apple developer account. macOS first-open approval for an unnotarized app can still apply. Manual upgrade steps remain in <a href="./install#upgrading">Upgrading</a>.</p>',129)])])}const L=t(P,[["render",q]]);export{E as __pageData,L as default};
